   140  static UA_NodeMapEntry *
   141  newEntry(UA_NodeClass nodeClass) {
   142      size_t size = sizeof(UA_NodeMapEntry) - sizeof(UA_Node);
   143      switch(nodeClass) {
   144      case UA_NODECLASS_OBJECT:
   145          size += sizeof(UA_ObjectNode);
   146          break;
   147      case UA_NODECLASS_VARIABLE:
   148          size += sizeof(UA_VariableNode);
   149          break;
   150      case UA_NODECLASS_METHOD:
   151          size += sizeof(UA_MethodNode);
   152          break;
   153      case UA_NODECLASS_OBJECTTYPE:
   154          size += sizeof(UA_ObjectTypeNode);
   155          break;
   156      case UA_NODECLASS_VARIABLETYPE:
   157          size += sizeof(UA_VariableTypeNode);
   158          break;
   159      case UA_NODECLASS_REFERENCETYPE:
   160          size += sizeof(UA_ReferenceTypeNode);
   161          break;
   162      case UA_NODECLASS_DATATYPE:
   163          size += sizeof(UA_DataTypeNode);
   164          break;
   165      case UA_NODECLASS_VIEW:
   166          size += sizeof(UA_ViewNode);
   167          break;
   168      default:
   169          return NULL;
   170      }
   171      UA_NodeMapEntry *entry = (UA_NodeMapEntry*)UA_calloc(1, size);
   172      if(!entry)
   173          return NULL;
   174      entry->node.nodeClass = nodeClass;
   175      return entry;
   176  }
