   229  static UA_Node *
   230  UA_NodeMap_newNode(void *context, UA_NodeClass nodeClass) {
   250  UA_NodeMap_getNode(void *context, const UA_NodeId *nodeid) {
   251      UA_NodeMap *ns = (UA_NodeMap*)context;
   252      BEGIN_CRITSECT(ns);
   253      UA_NodeMapEntry **entry = findOccupiedSlot(ns, nodeid);
   254      if(!entry) {
   255          END_CRITSECT(ns);
   256          return NULL;
   257      }
   258      ++(*entry)->refCount;
   259      END_CRITSECT(ns);
   260      return (const UA_Node*)&(*entry)->node;
