   263  static void
   264  UA_NodeMap_releaseNode(void *context, const UA_Node *node) {
   265      if (!node)
   266          return;
   267  #ifdef UA_ENABLE_MULTITHREADING
   268      UA_NodeMap *ns = (UA_NodeMap*)context;
   269  #endif
   270      BEGIN_CRITSECT(ns);
   271      UA_NodeMapEntry *entry = container_of(node, UA_NodeMapEntry, node);
   272      UA_assert(&entry->node == node);
   273      UA_assert(entry->refCount > 0);
   274      --entry->refCount;
   275      cleanupEntry(entry);
   276      END_CRITSECT(ns);
   277  }
