   306  static UA_StatusCode
   307  UA_NodeMap_removeNode(void *context, const UA_NodeId *nodeid) {
   308      UA_NodeMap *ns = (UA_NodeMap*)context;
   309      BEGIN_CRITSECT(ns);
   310      UA_NodeMapEntry **slot = findOccupiedSlot(ns, nodeid);
   311      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   312      if(slot)
   313          retval = clearSlot(ns, slot);
   314      else
   315          retval = UA_STATUSCODE_BADNODEIDUNKNOWN;
   316      END_CRITSECT(ns);
   317      return retval;
   318  }
